mapper.select:
SELECT dict_id, tenant_id, dict_code, dict_name, dict_type, parent_code, sort_order, enabled, remark, created_at, updated_at
FROM sys_data_dictionary WHERE tenant_id = #{tenantId}
AND dict_type = #{dictType}
ORDER BY sort_order ASC, created_at ASC

SELECT toggle_id, tenant_id, feature_code, feature_name, domain, enabled, description, config_json, created_at, updated_at
FROM sys_ai_feature_toggle WHERE tenant_id = #{tenantId}
AND domain = #{domain}
ORDER BY created_at ASC

mapper.update:
UPDATE sys_logistics_rule SET rule_name = #{ruleName}, base_cost = #{baseCost}, cost_per_kg = #{costPerKg},
       estimated_days_min = #{estimatedDaysMin}, estimated_days_max = #{estimatedDaysMax}, enabled = #{enabled},
       priority = #{priority}, updated_at = #{updatedAt}
WHERE rule_id = #{ruleId} AND tenant_id = #{tenantId}

mapper.select:
SELECT rule_id, tenant_id, rule_name, country_code, channel, weight_min_kg, weight_max_kg, base_cost, cost_per_kg, estimated_days_min, estimated_days_max, enabled, priority, created_at, updated_at
FROM sys_logistics_rule WHERE tenant_id = #{tenantId}
AND country_code = #{countryCode}
ORDER BY priority ASC, created_at DESC

SELECT rule_id, tenant_id, rule_name, country_code, channel, weight_min_kg, weight_max_kg, base_cost, cost_per_kg, estimated_days_min, estimated_days_max, enabled, priority, created_at, updated_at
FROM sys_logistics_rule WHERE tenant_id = #{tenantId} AND country_code = #{countryCode}
      AND enabled = true
      AND channel = #{channel}
ORDER BY priority ASC LIMIT 10

mapper.update:
UPDATE sys_connector_config SET connector_name = #{connectorName}, config = #{config}, status = #{status},
       version = #{version}, description = #{description}, last_sync_at = #{lastSyncAt}, updated_at = #{updatedAt}
WHERE config_id = #{configId} AND tenant_id = #{tenantId}

mapper.select:
SELECT config_id, tenant_id, connector_type, platform, connector_name, config, status, version, description, last_sync_at, created_at, updated_at
FROM sys_connector_config WHERE tenant_id = #{tenantId}
AND connector_type = #{connectorType}
AND platform = #{platform}
ORDER BY created_at ASC

SELECT setting_id, tenant_id, setting_type, setting_name, config, enabled, description, created_at, updated_at
FROM sys_invoice_setting WHERE tenant_id = #{tenantId}
AND setting_type = #{settingType}
ORDER BY created_at ASC

SELECT setting_id, tenant_id, channel, channel_name, rules, enabled, description, created_at, updated_at
FROM sys_notification_setting WHERE tenant_id = #{tenantId}
AND channel = #{channel}
ORDER BY created_at ASC

mapper.update:
UPDATE sys_notification_template SET template_name = #{templateName}, subject = #{subject}, content = #{content},
       variables = #{variables}, enabled = #{enabled}, description = #{description}, updated_at = #{updatedAt}
WHERE template_id = #{templateId} AND tenant_id = #{tenantId}

mapper.select:
SELECT template_id, tenant_id, template_code, template_name, channel, subject, content, variables, enabled, description, created_at, updated_at
FROM sys_notification_template WHERE tenant_id = #{tenantId}
AND channel = #{channel}
ORDER BY created_at ASC

SELECT log_id, tenant_id, user_id, username, module, action, target_object_type, target_object_id, detail, ip_address, user_agent, trace_id, operated_at
FROM sys_operation_log WHERE tenant_id = #{tenantId}
AND module = #{module}
AND user_id = #{userId}
ORDER BY operated_at DESC LIMIT 200

SELECT log_id, tenant_id, user_id, username, module, action, target_object_type, target_object_id, detail, ip_address, user_agent, trace_id, operated_at
FROM sys_operation_log WHERE tenant_id = #{tenantId} AND trace_id = #{traceId}
ORDER BY operated_at DESC

mapper.update:
UPDATE sys_data_masking_rule SET rule_name = #{ruleName}, mask_pattern = #{maskPattern}, replace_char = #{replaceChar},
       keep_prefix = #{keepPrefix}, keep_suffix = #{keepSuffix}, enabled = #{enabled}, description = #{description}, updated_at = #{updatedAt}
WHERE rule_id = #{ruleId} AND tenant_id = #{tenantId}

mapper.select:
SELECT rule_id, tenant_id, rule_code, rule_name, field_type, mask_pattern, replace_char, keep_prefix, keep_suffix, enabled, description, created_at, updated_at
FROM sys_data_masking_rule WHERE tenant_id = #{tenantId}
AND field_type = #{fieldType}
ORDER BY created_at ASC

SELECT version_id, tenant_id, rule_id, rule_type, rule_name, version, content_json, change_description, changed_by, created_at
FROM sys_business_rule_version WHERE tenant_id = #{tenantId}
AND rule_id = #{ruleId}
AND rule_type = #{ruleType}
ORDER BY version DESC

SELECT log_id, tenant_id, rule_id, rule_version, rule_type, business_type, reference_id, input_context, output_result, success, error_message, execution_time_ms, executed_at
FROM sys_rule_execution_log WHERE tenant_id = #{tenantId}
AND rule_id = #{ruleId}
AND business_type = #{businessType}
ORDER BY executed_at DESC

SELECT log_id, tenant_id, rule_id, rule_version, rule_type, business_type, reference_id, input_context, output_result, success, error_message, execution_time_ms, executed_at
FROM sys_rule_execution_log WHERE tenant_id = #{tenantId} AND reference_id = #{referenceId}
ORDER BY executed_at DESC

SELECT replay_id, tenant_id, rule_id, rule_version, rule_type, input_context, output_result, passed, error_message, replayed_at
FROM sys_simulation_replay WHERE tenant_id = #{tenantId}
AND rule_id = #{ruleId}
ORDER BY replayed_at DESC

SELECT endpoint_id, tenant_id, name, url, event_type, headers, secret, active, retry_count, timeout_seconds, subscribed_events, created_at, updated_at
FROM sys_webhook_endpoint WHERE tenant_id = #{tenantId}
ORDER BY created_at ASC

SELECT delivery_id, tenant_id, endpoint_id, event_type, payload, status_code, response, success, attempt_count, next_retry_at, delivered_at
FROM sys_webhook_delivery WHERE tenant_id = #{tenantId}
AND endpoint_id = #{endpointId}
ORDER BY delivered_at DESC

SELECT task_id, tenant_id, import_type, file_name, file_size, status, total_rows, success_rows, failed_rows, column_mapping, error_report_url, imported_by, started_at, completed_at
FROM sys_manual_import_task WHERE tenant_id = #{tenantId}
AND import_type = #{importType}
ORDER BY started_at DESC

SELECT template_id, tenant_id, template_code, template_name, template_type, content, paper_size, orientation, variables, enabled, description, created_at, updated_at
FROM sys_print_template WHERE tenant_id = #{tenantId}
AND template_type = #{templateType}
ORDER BY created_at ASC

SELECT event_id, tenant_id, event_code, event_name, domain, aggregate_type, event_type, description, payload_schema, subscribers, version, enabled, created_at, updated_at
FROM sys_domain_event_catalog WHERE tenant_id = #{tenantId}
AND domain = #{domain}
ORDER BY domain ASC, event_code ASC

SELECT alert_id, tenant_id, alert_type, alert_code, severity, domain, title, description, source_type, source_id, status, assigned_to, resolution, occurred_at, resolved_at, created_at, updated_at
FROM sys_business_alert WHERE tenant_id = #{tenantId}
AND alert_type = #{alertType}
AND status = #{status}
ORDER BY occurred_at DESC

SELECT draft_id, tenant_id, erp_reference_id, domain, draft_type, target_business_type, target_business_id, content_json, trust_level, source_system, actor_id, actor_type, agent_id, scope, purpose, trace_id, approval_status, approved_by, approved_at, execution_status, execution_result, created_at, updated_at
FROM sys_pms_draft_document WHERE tenant_id = #{tenantId}
AND domain = #{domain}
ORDER BY created_at DESC

SELECT feedback_id, tenant_id, erp_reference_id, recommendation_id, domain, feedback_type, execution_status, business_result, business_metrics_json, failure_reason, operator_id, trace_id, delivered, retry_count, delivered_at, created_at, updated_at
FROM sys_pms_feedback WHERE tenant_id = #{tenantId}
ORDER BY created_at DESC

SELECT rule_id, tenant_id, domain, object_type, trust_level, description, allowed_actions, can_overwrite_erp, created_at, updated_at
FROM sys_pms_data_trust_rule WHERE tenant_id = #{tenantId}
ORDER BY domain ASC, object_type ASC

SELECT log_id, tenant_id, config_id, connector_type, platform, endpoint, method, trace_id, status_code, duration_ms, success, error_message, called_at
FROM sys_connector_call_log WHERE tenant_id = #{tenantId}
AND config_id = #{configId}
ORDER BY called_at DESC

SELECT secret_id, tenant_id, config_id, key_type, encrypted_value, masked_preview, last_rotated_by, last_rotated_at, created_at, updated_at
FROM sys_connector_secret WHERE tenant_id = #{tenantId}
AND config_id = #{configId}
