SELECT rule_id, tenant_id, rule_type, category, keyword, keyword_pattern, severity, action, replacement, description, enabled, applicable_platforms, created_at, updated_at
FROM sys_content_audit_rule WHERE tenant_id = #{tenantId}
AND rule_type = #{ruleType}
AND enabled = #{enabled}
ORDER BY severity DESC, created_at ASC

SELECT result_id, tenant_id, audit_type, source_type, source_id, passed, violations, audited_by, audited_at
FROM sys_content_audit_result WHERE tenant_id = #{tenantId}
AND source_type = #{sourceType}
ORDER BY audited_at DESC

SELECT trademark_id, tenant_id, trademark_name, registration_number, jurisdiction, nice_classes, owner, status, registered_at, expires_at, created_at, updated_at
FROM sys_trademark_record WHERE tenant_id = #{tenantId}
AND status = #{status}
